/bin/bash -lc "node --input-type=module <<'NODE'
const cases = [
  { member: 'Ada', team: 'Design', region: 'eu-west' },
  { member: 'Lin', team: 'Platform', region: 'ap-south' },
]
for (const current of cases) {
  const response = await fetch('http://localhost:3117/', {
    headers: {
      cookie: "'`member=${current.member}; team=${current.team}`,
      '"'x-region': current.region,
    },
  })
  const html = await response.text()
  const checks = {
    workspace: html.includes('Workspace'),
    projectTotals: html.includes('12 active projects') && html.includes('4 archived projects'),
    loadingFrame: html.includes('Loading your workspace details'),
    member: html.includes("'`Welcome, ${current.member}`),
    team: html.includes(`Team: ${current.team}`),
    region: html.includes(`Region: ${current.region}`),
    otherMemberAbsent: !html.includes(`Welcome, ${current.member === '"'Ada' ? 'Lin' : 'Ada'}"'`),
  }
  console.log(current.member, response.status, checks)
  if (response.status !== 200 || Object.values(checks).some((value) => !value)) process.exitCode = 1
}
NODE'

