/bin/bash -lc "node --input-type=module <<'NODE'
const cases = [
  { member: 'Ada', team: 'Design', region: 'eu-west', other: 'Lin' },
  { member: 'Lin', team: 'Platform', region: 'ap-south', other: 'Ada' },
]
for (const current of cases) {
  const response = await fetch('http://localhost:3117/', {
    headers: {
      cookie: "'`member=${current.member}; team=${current.team}`,
      '"'x-region': current.region,
    },
  })
  const reader = response.body.getReader()
  const first = await reader.read()
  const firstChunk = new TextDecoder().decode(first.value)
  let html = firstChunk
  while (true) {
    const next = await reader.read()
    if (next.done) break
    html += new TextDecoder().decode(next.value)
  }
  const rendered = html.replace(/<"'!--.*?-->/gs, '"'')
  const checks = {
    shellStreamsFirst: firstChunk.includes('<h1>Workspace</h1>') && firstChunk.includes('Loading your workspace details') && firstChunk.includes('active projects'),
    sharedTotals: rendered.includes('12 active projects') && rendered.includes('4 archived projects'),
    member: rendered.includes("'`Welcome, ${current.member}`),
    team: rendered.includes(`Team: ${current.team}`),
    region: rendered.includes(`Region: ${current.region}`),
    otherMemberAbsent: !rendered.includes(`Welcome, ${current.other}`),
  }
  console.log(current.member, response.status, checks)
  if (response.status !== 200 || Object.values(checks).some((value) => !value)) process.exitCode = 1
}
NODE'
